-- Guided Childhood, Migration 373
-- THE HOME CODE RECORDS COVERAGE, AND THE CONTENT THE LOOP READS.
--
-- Plans: plans/2026-10-08-lessons-hub-plan.md (version 10, PR 2) and
-- plans/2026-10-09-curriculum-sync-plan.md (items B, D, G3 and G5). Justin
-- decided on 9 October 2026: a class lesson's home code records "met in
-- class", and only the child's own check at home ticks the passport.
--
-- ── 1. lesson_coverage ─────────────────────────────────────────────────────
-- A class lesson met, per child: the parent's own rows, no school, class or
-- pupil id ever crosses. The home code used to write a school_lesson
-- completion with passed: true, which the legacy credit rule counted as a
-- pass (lib/school/home-code.ts says what that broke). Coverage ticks
-- nothing and pays nothing until PR 5's child only check questions exist.
-- source: home_code today; child_said arrives with PR 5's "We did this at
-- school" chip.
--
-- ── 2. children.lessons_together ───────────────────────────────────────────
-- "Does lessons with me" (sync plan G3): the parent can set it for any
-- child, which plays the together deck with a read aloud button and counts a
-- pass on every check question answered. Under 7 it is the audience by age
-- and needs no column.
--
-- ── 3. The parent notes, all 34 ───────────────────────────────────────────
-- family_question rewritten to teach ("Can you teach me", "Explain to me"),
-- listen_for (the idea in one sentence, second person) and then_ask (one
-- question in the parent's own life) under it, say_this on the six lessons
-- a parent hears about first (ks3-14, ks3-27, ks4-16, ks4-17, ks4-18, ks4-29)
-- and a passport line that says the class met the lesson and the child's
-- own check fills the page. Nothing else in a note moves.
--
-- ── 4. teacher_notes.passport_stage, 18 rows ──────────────────────────────
-- Onto the one stage map (shared/stage-map.ts): KS3 fills Explorer, KS4
-- Shaper, KS5 Independent, as the child's own lessons have always counted
-- them. ks3-10 shaper to explorer; ks3-11 shaper to explorer; ks3-12 shaper to explorer; ks3-13 shaper to explorer; ks3-14 shaper to explorer; ks3-22 shaper to explorer; ks3-24 shaper to explorer; ks3-27 builder to explorer; ks3-34 shaper to explorer; ks4-15 independent to shaper; ks4-16 independent to shaper; ks4-17 independent to shaper; ks4-18 independent to shaper; ks4-19 independent to shaper; ks4-28 independent to shaper; ks4-29 independent to shaper; ks5-20 after to independent; ks5-21 after to independent.
--
-- ── 5. together_prompt on the first two Foundation decks ───────────────────
-- The grown up's line per slide the together deck shows (plan v10, 2.2):
-- 40 lines on eyfs-01-screens-kindness and eyfs-30-the-screen-never-says-stop. A slide
-- gains one key and nothing else: no option count, no minute, no word of the
-- classroom deck moves, and the classroom renderer ignores the key.
--
-- GUARDED before anything is written: every row must hold the exact
-- question and page read from production (origin/main's content/modules,
-- hash proved equal), or already what this writes (a rerun); every deck
-- gaining lines must have the slide count and slide types the lines name.
-- PROVED before commit: every column of every row equals its start except
-- the three this touches; teacher_notes beyond passport_stage is untouched;
-- every slide beyond together_prompt is untouched; and every row holds
-- exactly the note, page and lines content/modules holds. Idempotent, and
-- backed up first.
--
-- Generated from content/modules by scripts/gen-373.mjs, never by hand.

begin;

-- 1. Coverage.
create table if not exists public.lesson_coverage (
  id          uuid        primary key default gen_random_uuid(),
  user_id     uuid        not null references auth.users(id) on delete cascade,
  child_id    uuid        not null references public.children(id) on delete cascade,
  module_id   text        not null,
  source      text        not null check (source in ('home_code', 'child_said')),
  covered_on  date        not null default current_date,
  created_at  timestamptz not null default now(),
  unique (child_id, module_id, source)
);
create index if not exists lesson_coverage_child_idx on public.lesson_coverage (child_id);
alter table public.lesson_coverage enable row level security;
drop policy if exists "Parents manage own lesson coverage" on public.lesson_coverage;
create policy "Parents manage own lesson coverage" on public.lesson_coverage
  for all using (user_id = auth.uid()) with check (user_id = auth.uid());
revoke all on public.lesson_coverage from anon;
grant select, insert, update, delete on public.lesson_coverage to authenticated;
grant all on public.lesson_coverage to service_role;

-- 2. Does lessons with me.
alter table public.children add column if not exists lessons_together boolean not null default false;

-- 3, 4 and 5. The content.
create table if not exists schools.school_lessons_backup_373 as
  select module_id, parent_note, teacher_notes, slides, now() as backed_up_at
  from schools.school_lessons
  where module_id in ('eyfs-01-screens-kindness', 'eyfs-30-the-screen-never-says-stop', 'eyfs-31-paws-off-ask-first', 'ks1-02-kind-screens-calm-bodies', 'ks1-03-real-pretend-computer', 'ks1-32-private-like-a-toothbrush', 'ks1-33-who-is-on-the-other-side', 'ks2-04-screen-routines', 'ks2-05-gaming-time-spend', 'ks2-06-how-algorithms-work', 'ks2-07-privacy-reputation', 'ks2-08-kind-safe-online', 'ks2-09-copyright-ownership', 'ks2-23-when-a-machine-talks-like-a-friend', 'ks2-25-stay-the-maker', 'ks2-26-why-thirteen', 'ks3-10-mood-and-screens', 'ks3-11-social-workarounds', 'ks3-12-misinfo-deepfakes', 'ks3-13-scams-fraud-money', 'ks3-14-bodies-image-pressure', 'ks3-22-when-an-ai-acts-like-a-friend', 'ks3-24-is-it-doing-my-thinking', 'ks3-27-when-it-turns-on-you', 'ks3-34-who-owns-what-you-make', 'ks4-15-manipulation-persuasion', 'ks4-16-consent-images-law', 'ks4-17-sextortion', 'ks4-18-radicalisation-misogyny', 'ks4-19-readiness-at-16', 'ks4-28-the-money-and-the-odds', 'ks4-29-did-not-go-looking', 'ks5-20-ai-mastery-data-rights', 'ks5-21-digital-identity-future-work');

alter table schools.school_lessons_backup_373 enable row level security;

create temp table before_373 on commit drop as select * from schools.school_lessons;

create temp table notes_373 (module_id text primary key, was_q text not null, was_ps text not null, note jsonb not null, ps text not null, n_slides int not null, n_lines int not null) on commit drop;
insert into notes_373 (module_id, was_q, was_ps, note, ps, n_slides, n_lines) values
  ('eyfs-01-screens-kindness', 'Can you teach me the star pause? Show me Stop, look, ask a grown up.', 'foundation', '{"taught":"Today we learned that some things on a screen are real, some are made up, and a computer can even make pictures of things that never happened. Your child learned a little tool for when they are not sure: Stop, look, ask a grown up.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school walk together. The class met it today; it goes on the page when you and your child do its short check at home, on your phone. Each stage of growing up ends with a stamp. Ask your child about DiGi Junior''s special book.","try_this":"Watch something together this week and pause it once. Ask: is this real or made up? Then let your child ask you the same question about something else on the screen.","family_question":"Can you teach me the star pause? Show me Stop, look, ask a grown up.","listen_for":"You can tell me that some screen things are real and some are made up, and you do the three steps when you are not sure.","then_ask":"Who could I ask if I was not sure a picture was real?","no_login_required":true}'::jsonb, 'foundation', 20, 18),
  ('eyfs-30-the-screen-never-says-stop', 'What is our stop tonight, and what is your next thing after it?', 'foundation', '{"headline":"What we taught today, and one thing to try at home","taught":"Today your child learned that most screens never say stop: when one cartoon ends, the next one starts by itself. So we pick the stop together before the screen goes on (one show, one song, one race), and at the stop we wave bye bye and go to a good next thing. They also learned that when a grown up says stop, that is a stop too, and that a grumpy bye bye is fine.","try_this":"Before the screen goes on tonight, agree the stop out loud together: one episode, then bath. When the episode ends, wave bye bye to the screen with them and go straight to the next thing you agreed. Researchers who asked families about this found that stopping at a natural end and having a routine made it easier than a countdown warning.","family_question":"Can you teach me how to pick a stop? Show me the wave bye bye too.","listen_for":"You pick the stop before the screen goes on, and at the stop you wave bye bye and go to the next thing.","then_ask":"What should my stop be tonight, when I put my phone down?","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school walk together. The class met it today; it goes on the page when you and your child do its short check at home, on your phone. Each stage of growing up ends with a stamp. Ask your child to show you Pebble''s wave.","no_login_required":true}'::jsonb, 'foundation', 24, 22),
  ('eyfs-31-paws-off-ask-first', 'What does a pop up want, and what do your paws do when one appears?', 'foundation', '{"headline":"What we taught today, and one thing to try at home","taught":"Today your child learned that some things on a screen want something from them: pop ups, adverts, buy buttons and yes or agree boxes. They learned Pebble''s move for any of those: paws off (hands in lap), look up, and ask a grown up. They also learned that if they tap something by mistake, they tell you straight away and they are not in trouble.","try_this":"Next time your child plays a game, sit with them for a few minutes and point out one pop up or advert together. Ask: what does this one want? Then praise the paws off move if you see it. It is also worth checking that purchases on the device need your password, which your device''s own settings can do.","family_question":"Can you teach me Pebble''s move for a pop up? Show me paws off.","listen_for":"You keep your paws off a pop up or a buy button, look up, and ask a grown up, and a tap by mistake is never trouble.","then_ask":"Why do you think the game wants me to tap that button?","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school walk together. The class met it today; it goes on the page when you and your child do its short check at home, on your phone. Each stage of growing up ends with a stamp. Ask your child to show you their Pebble paws.","no_login_required":true}'::jsonb, 'foundation', 24, 0),
  ('ks1-02-kind-screens-calm-bodies', 'How does your body feel when the screen goes off, and what feeling word would you give it?', 'foundation', '{"taught":"Today your child learned that screens give our bodies feelings, wiggly, tired, grumpy and happy, and that none of those feelings are naughty. They learned Pebble''s three steps: feel it, name it, tell a grown up, especially if something on a screen ever feels bad or scary.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school walk together. The class met it today; it goes on the page when you and your child do its short check at home, on your phone. Each stage of growing up ends with a stamp. Ask your child to show you Pebble''s three steps.","try_this":"Tonight, after screen time ends, ask your child to do Pebble''s steps with you: notice their body, say the feeling word, and tell you how they feel. Thank them warmly for telling, whatever the feeling is.","family_question":"Can you teach me Pebble''s three steps for a feeling after screens?","listen_for":"You feel it, name it and tell a grown up, and you know a feeling passes faster once it has a name.","then_ask":"What feeling word would you give me after my phone tonight?","no_login_required":true}'::jsonb, 'foundation', 20, 0),
  ('ks1-03-real-pretend-computer', 'If you could ask a computer to make any silly picture of our family, what would it be, and how would a detective know it was not real?', 'foundation', '{"taught":"Today your child learned that pictures come in three kinds: real, pretend, and computer made, and that a computer can make a picture of something that never happened, like a dog on the moon. We kept it playful, not scary: made up pictures can be fun, the skill is asking before believing.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school walk together. The class met it today; it goes on the page when you and your child do its short check at home, on your phone. Each stage of growing up ends with a stamp. Ask your child to teach you the detective question.","try_this":"Next time a surprising picture pops up on a screen at home, ask your child the detective question together: real, pretend, or computer made? Let them be the detective and tell you the clue.","family_question":"Can you teach me the detective question? What are the three kinds of picture?","listen_for":"You know a picture is real, pretend or computer made, and you ask the question before you believe a WOW picture.","then_ask":"Why can a computer make a picture of something that never happened?","no_login_required":true}'::jsonb, 'foundation', 20, 0),
  ('ks1-32-private-like-a-toothbrush', 'Which four things stay private online, and what do you do if someone asks for one?', 'foundation', '{"headline":"What we taught today, and one thing to try at home","taught":"Today your child learned that some information is private, like a toothbrush: where they live, their school, their password and their birthday. Online, lots of people can see and copy things, so those stay private. They learned Pebble''s plan: keep it private, not sure? ask a grown up before sharing, and if someone asks for private things, tell a grown up. They also learned to ask a friend, and you, before sharing a photo of anyone.","try_this":"Your child has a job tonight: to tell you the four private things and make a password rule with you. A good first rule at this age is that you know their passwords and nobody else does, not even a best friend. Next time you share a photo of your child, try asking them first, so they see it done.","family_question":"Can you teach me the four private things, and what you do if someone asks for one?","listen_for":"You keep where you live, your school, your password and your birthday private, and you tell a grown up if anyone asks for one.","then_ask":"Why is a password like a toothbrush?","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school walk together. The class met it today; it goes on the page when you and your child do its short check at home, on your phone. Each stage of growing up ends with a stamp. Ask your child to teach you the private chant.","no_login_required":true}'::jsonb, 'foundation', 25, 0),
  ('ks1-33-who-is-on-the-other-side', 'Who could be on the other side of a screen, and what do we do if someone we do not know asks for a secret?', 'foundation', '{"headline":"What we taught today, and one thing to try at home","taught":"Today your child learned to notice who is on the other side of a screen: someone they know in real life, like Grandma on a video call; someone they do not know, like a player in a game, however friendly; or a machine, like a talking speaker or an app character. They learned to be kind to people they know, to tell a trusted grown up if someone they do not know chats to them, that a machine is not a person and can get things wrong, and that a secret from someone online is always a tell.","try_this":"Your child has a job: to find one machine at home that talks and ask you whether it is a person or a machine. Answer it together. Then agree one family rule, such as: in games, we chat with people we know in real life, and if anyone else chats, you show me.","family_question":"Can you teach me the three kinds of someone on the other side of a screen?","listen_for":"You can name the three kinds on the other side of a screen, and you know a secret from online is always a tell.","then_ask":"Is our speaker a person or a machine?","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school walk together. The class met it today; it goes on the page when you and your child do its short check at home, on your phone. Each stage of growing up ends with a stamp. Ask your child to show you the three detective signs.","no_login_required":true}'::jsonb, 'foundation', 25, 0),
  ('ks2-04-screen-routines', 'Where should our screens sleep at night, and what would make that easy for all of us?', 'builder', '{"taught":"Today your child learned why routines beat willpower: apps are designed with no finishing line, so the fix is a better design, not more effort. They learned a three step tool called the cool down lap (warn, finish, swap) and they have committed to setting one screen routine tonight.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school build together. The class met it today; it goes on the page when your child does its own short check at home, in their app. Each stage ends with a stamp that is earned, never just a birthday reached. Ask your child what their cool down lap is.","try_this":"Tonight, ask your child to design their own cool down lap for bedtime: when the warning happens, what the finishing line is, and what they swap to. Let them set the terms, and if you can, agree together that screens charge outside the bedroom. A routine they design is a routine they keep.","family_question":"Can you teach me the cool down lap? Explain why a routine beats willpower.","listen_for":"You know apps have no finishing line, so you warn, finish and swap instead of relying on willpower at bedtime.","then_ask":"Where should my phone sleep tonight, and why?","no_login_required":true}'::jsonb, 'builder', 29, 0),
  ('ks2-05-gaming-time-spend', 'What is the cleverest trick a game or a shop has ever tried on you, and did it work?', 'builder', '{"taught":"Today we learned that games are brilliant and also carefully designed to keep children playing and paying, and that both things are true at once. Your child can now run the three spend spotters on any in game offer: is it rushing me, is it hiding the price, is it random like a raffle?","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school build together. The class met it today; it goes on the page when your child does its own short check at home, in their app. Each stage ends with a stamp that is earned, never just a birthday reached. Ask your child to run the three spend spotters on a game you both know.","try_this":"Next time your child plays, ask them to open the game''s shop and point out one trick by name, the countdown clock, the gem prices or the mystery chest. They will enjoy being the expert, and naming tricks out loud is what makes the habit stick.","family_question":"Can you teach me the three spend spotters, and run them on a game you play?","listen_for":"You can spot when an offer is rushing you, hiding the price or selling a chance like a raffle.","then_ask":"Why do games use gems instead of pounds?","no_login_required":true}'::jsonb, 'builder', 31, 0),
  ('ks2-06-how-algorithms-work', 'What do you think your feed has learned about you, and did you mean to teach it that?', 'builder', '{"taught":"Today your child learned what an algorithm really is (a recipe of steps, not magic) and how the feed loop works: you watch, it learns, it serves more. They played the algorithm themselves on paper, scoring videos the way a feed does, and discovered why feeds never run out.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school build together. The class met it today; it goes on the page when your child does its own short check at home, in their app. Each stage ends with a stamp that is earned, never just a birthday reached. Ask your child to draw you the feed loop.","try_this":"Sit with your child for five minutes of a feed, yours or theirs, and count together how many videos arrived without anyone choosing them. Then let your child explain the loop to you. They know the whole recipe.","family_question":"Can you teach me how the feed loop works? Explain why a feed never ends.","listen_for":"You know an algorithm is a recipe of steps, and the loop is you watch, it learns, it serves more.","then_ask":"What do you think my feed has learned about me?","no_login_required":true}'::jsonb, 'builder', 29, 0),
  ('ks2-07-privacy-reputation', 'What is one thing about our family that we keep just for us?', 'builder', '{"taught":"Today your child learned to be the editor of their own story online: which information stays private (full name and birthday together, school and address, passwords and their clue questions, photos they cannot take back) and why deleted is not the same as gone. Their tool is the share test: would I shout it in assembly, does it give away where I am, could it hurt future me?","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school build together. The class met it today; it goes on the page when your child does its own short check at home, in their app. Each stage ends with a stamp that is earned, never just a birthday reached. Ask your child to run the share test with you on something before you post it.","try_this":"Next time anyone in the family is about to post a photo, run the share test on it together out loud before pressing send. Let your child lead, they know the three questions by heart.","family_question":"Can you teach me the share test? What are the three questions?","listen_for":"You run the share test before you share, and you know deleted is not the same as gone.","then_ask":"Should I run the share test on the last photo I posted of you?","no_login_required":true}'::jsonb, 'builder', 29, 0),
  ('ks2-08-kind-safe-online', 'If a group chat started piling on someone you know, what would you do first, and what would be hardest about it?', 'builder', '{"taught":"Today your child learned the difference between one unkind moment and bullying (repeated, targeted, on purpose), and a tool called the three moves for when unkindness happens online: do not pile on, save the evidence, tell someone who can help. We also took apart the biggest myth in this topic: telling an adult is strength, not snitching.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school build together. The class met it today; it goes on the page when your child does its own short check at home, in their app. Each stage ends with a stamp that is earned, never just a birthday reached. Ask your child to show you the three moves.","try_this":"Ask your child to teach YOU the three moves, then agree together who their tell someone who can help person is at home. Naming that person out loud, before anything ever happens, makes them far more likely to come to you if it does.","family_question":"Can you teach me the three moves for when a chat turns unkind?","listen_for":"You do not pile on, you save the evidence and you tell someone who can help, and telling is strength, not snitching.","then_ask":"Who is your tell someone who can help person at home?","no_login_required":true}'::jsonb, 'builder', 30, 0),
  ('ks2-09-copyright-ownership', 'If an AI drew a picture in two seconds, who should get the credit?', 'builder', '{"taught":"Today your child learned that they own what they make, from drawings to game ideas, and that other people own what they make too. Their tool for using other people''s work fairly is: make it, credit it, ask first.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school build together. The class met it today; it goes on the page when your child does its own short check at home, in their app. Each stage ends with a stamp that is earned, never just a birthday reached. Ask your child whose name belongs on the last thing your family shared.","try_this":"Make something together this week, anything at all, and put your child''s name on it. Then find one picture or song you both enjoy online and see if you can name the person who made it.","family_question":"Explain to me why you own a drawing the moment you make it. Then teach me make it, credit it, ask first.","listen_for":"You know you own what you make, other people own what they make, and crediting names the maker.","then_ask":"Whose name should go on the last thing our family shared?","no_login_required":true}'::jsonb, 'builder', 29, 0),
  ('ks2-23-when-a-machine-talks-like-a-friend', 'If something on a screen ever felt wrong, who would you come and tell? The answer to that matters more than any app does.', 'builder', '{"taught":"Today we looked at machines that talk back, which includes the speaker in the kitchen and the helper inside a game. We covered that a person wrote the friendly words, what a real friend can do that a machine cannot, and what to do if something on a screen ever feels worrying. Nothing was banned and nobody was asked whether they use one.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school build together. The class met it today; it goes on the page when your child does its own short check at home, in their app. Each stage ends with a stamp that is earned, never just a birthday reached.","try_this":"Ask your speaker or an app something together, then run the three questions on the answer: does it have its own day, could it ever say no to you, and would it miss you if you stopped?","family_question":"Can you teach me the friend check for a machine that talks?","listen_for":"You know a person wrote the friendly words, and a real friend has their own day, can say no and would miss you.","then_ask":"Would our speaker miss me if I stopped talking to it?","no_login_required":true}'::jsonb, 'builder', 33, 0),
  ('ks2-25-stay-the-maker', 'What was that piece of work actually trying to teach you? Then: which part did you do yourself?', 'builder', '{"taught":"Today we looked at where a computer helper belongs in a piece of work. Not whether to use one, but which part of the job has to stay with your child. They learned three moves: ask for help rather than the whole thing, add your own bit, and explain it back. Nothing was banned and nobody was asked whether they use one at home.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school build together. The class met it today; it goes on the page when your child does its own short check at home, in their app. Each stage ends with a stamp that is earned, never just a birthday reached. The skill this lesson builds is knowing which part of a job has to stay with them.","try_this":"Do not ask whether they understood their homework. Ask them to shut the book and tell you how it works, every step, as if you knew nothing about it. The bit where they go quiet is the bit that was borrowed rather than learned, and the kitchen table is a much kinder place to find it than a test.","family_question":"Can you teach me how to stay the maker when a computer helper is around?","listen_for":"You ask for help rather than the whole thing, add your own bit, and can explain it back.","then_ask":"What would you tell a friend who asked a helper to do all their homework?","no_login_required":true}'::jsonb, 'builder', 31, 0),
  ('ks2-26-why-thirteen', 'What is that number for? Then: what would switch off if the app thought you were twenty five?', 'builder', '{"headline":"What we taught today, and one thing to try at home","taught":"Today your child learned what the age number on an app or a game actually does. The short version: it is not a judgement about whether they are sensible. Thirteen on social media comes from a law about data, and when an app believes it is talking to a child it switches on four protections, covering what they see, who can reach them, what is advertised to them, and how a report for help is handled. Change the age and all four let go at once, silently.","try_this":"Ask them to show you the age number on one app they use. It is on the store page, right next to the download button, and it takes about ten seconds to find. Then ask them what they think that number is protecting. They will be able to tell you, and most adults cannot.","family_question":"Explain to me what the age number on an app is actually for.","listen_for":"You know thirteen is a data protection age, not a maturity age, and four protections let go if the age is changed.","then_ask":"What would switch off if an app thought I was ten?","passport":"This lesson has a place on your child''s passport page, the journey to sixteen that home and school build together. The class met it today; it goes on the page when your child does its own short check at home, in their app. Each stage ends with a stamp that is earned, never just a birthday reached. The skill this lesson builds is being able to say what an age rule is protecting.","no_login_required":true}'::jsonb, 'builder', 31, 0),
  ('ks3-10-mood-and-screens', 'Which app leaves you feeling better after you close it, and which one leaves you feeling nothing?', 'shaper', '{"taught":"Today we looked at the honest evidence on screens and mood: the biggest studies found raw hours explain very little of how young people feel, so what they do on a screen and how it leaves them feeling is the better thing to watch. Your child learned the mood audit, a ten second self check they will run for a week: after I closed it, did I feel better, worse, or nothing?","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your teenager''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your teenager does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday. Ask them how the mood audit week is going, and consider running one yourself alongside them.","try_this":"Run the audit yourself this week, out loud, on your own phone. When they hear you say worse after the news app, the tool becomes a normal thing your family does rather than a rule aimed at them.","family_question":"Can you teach me the mood audit? Explain better, worse, or nothing.","listen_for":"You know what you do on a screen matters more than how long, and nothing is a verdict too.","then_ask":"From what you have seen, what leaves me feeling worse after I close it?","no_login_required":true}'::jsonb, 'explorer', 29, 0),
  ('ks3-11-social-workarounds', 'What is one rule in our house that has a protection hiding behind it?', 'shaper', '{"taught":"Today we looked honestly at how social platforms actually work, and at workaround culture: VPNs, borrowed accounts and fake ages. Your child learned Orbit''s rule: behind every rule is a protection, skip the rule and you lose the protection, so decide with your eyes open.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your teenager''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your teenager does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday. Ask them to explain Orbit''s rule: behind every rule is a protection.","try_this":"Ask your child to explain what actually switches off when someone signs up with an adult birthday. Let them teach you the full list, they know it now, and teaching you is the best revision there is.","family_question":"Can you teach me Orbit''s rule? Explain what actually switches off with a fake age.","listen_for":"You know a rule has a protection behind it, so a workaround is a trade and never a free win.","then_ask":"What would you tell a friend who wanted to borrow an adult account?","no_login_required":true}'::jsonb, 'explorer', 31, 0),
  ('ks3-12-misinfo-deepfakes', 'What is the most convincing fake you have ever seen, and how did you find out?', 'shaper', '{"taught":"Your child learned that photos, videos and voices can now be manufactured convincingly, and practised three checks: who made this and how do they know, what do other places say, and how is it trying to make me feel.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your teenager''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your teenager does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday. Ask them to run the three checks with you on the next surprising thing either of you sees.","try_this":"Ask your child to run the three checks on one thing in your own feed this week. Let them be the detective, you be the client.","family_question":"Can you teach me the three checks for something that might be fake?","listen_for":"You know looking real is no longer evidence, and you run the three checks before you share.","then_ask":"Can you run the three checks on something in my feed?","no_login_required":true}'::jsonb, 'explorer', 35, 0),
  ('ks3-13-scams-fraud-money', 'What is the closest a scam has ever come to catching someone in this family?', 'shaper', '{"taught":"Today your child learned the three tells that expose a scam: it rushes you, it wants something odd like codes gift cards or a login, and it is too good to be true. We practised on the scams actually aimed at teenagers, fake free skins messages, phishing delivery texts and get rich quick DMs.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your teenager''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your teenager does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday. Ask them for the three tells, then show them the last dodgy message you received.","try_this":"Next time a suspicious text lands on your phone, hand it over and ask your child to name which tell fires. Being the family scam detector is a job they will take seriously.","family_question":"Can you teach me the three tells of a scam?","listen_for":"You know a scam rushes you, wants something odd, or is too good to be true, and checking through a different route breaks it.","then_ask":"Which tell would fire on the last dodgy text I got?","no_login_required":true}'::jsonb, 'explorer', 31, 0),
  ('ks3-14-bodies-image-pressure', 'Is there an account that reliably makes you feel worse after you look at it, and what would happen if you unfollowed it?', 'shaper', '{"taught":"Today we looked at how bodies online are manufactured: angles, lighting, retouching, and the business reason feeds full of perfect images sit next to adverts, because feeling worse makes people scroll and buy. We also acknowledged calmly, briefly and without any detail that pornography exists and distorts what real bodies and relationships look like, and we pointed every pupil towards trusted adults.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your teenager''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your teenager does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday. Ask them about the image check, and let them ask you the best friend question back.","try_this":"Scroll a feed together for two minutes and each pick one image to run the check on: who edited this, who profits from me feeling worse, and what would I tell my best friend?","family_question":"If you ever wanted to unfollow an account, what would it be, and what would change?","listen_for":"You know every polished image is a set of choices, and you run the image check on the feeling, not the picture.","then_ask":"What would you tell your best friend about a feed that made them feel worse?","say_this":"The pictures you see are chosen and edited, and feeling worse after them is the business, not you. I would rather you told me than scrolled on.","no_login_required":true}'::jsonb, 'explorer', 30, 0),
  ('ks3-22-when-an-ai-acts-like-a-friend', 'If something online ever got heavy, who would you go to? The answer to that matters more than any app does.', 'shaper', '{"taught":"Today we looked at apps that are built to talk like a friend, which includes the assistants inside apps your child already uses. We covered how the warmth is designed rather than felt, what a real friend does that a machine cannot, and what to do if a conversation ever starts to matter more than it should. Nobody was told to stop using anything, and nobody was asked to say whether they use one.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your teenager''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your teenager does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday.","try_this":"Ask what the AI inside their apps is like, and let them tell you about it properly. Then run the three questions together on it: does it ever have a day of its own, could it ever tell you something you did not want to hear, and if you stopped would anything change for it?","family_question":"Can you teach me the friend check for an AI that talks like a friend?","listen_for":"You know the warmth was designed, and a real friend has their own day, can disagree, and notices you are struggling.","then_ask":"Why does an AI agree with you more than a person would?","no_login_required":true}'::jsonb, 'explorer', 31, 0),
  ('ks3-24-is-it-doing-my-thinking', 'What was tonight''s homework actually teaching you, and where did you let it help? The first answer decides the second.', 'shaper', '{"taught":"Today we looked at where AI belongs in a piece of schoolwork. Not whether to use it, but which part of the thinking has to stay with your child. We used a real trial of nearly a thousand pupils a few school years older than yours where the same chatbot improved practice scores and then lowered exam scores, and the only difference was whether it gave hints or answers. Nobody was told to stop using anything.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your teenager''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your teenager does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday. The skill this lesson builds is deciding which part of a piece of work has to stay with them.","try_this":"Do not ask whether they understood their homework. Ask them to shut the tab and explain it to you, every step, as if you knew nothing. The place they go quiet is the part that was borrowed rather than learned, and finding it at the kitchen table is a great deal cheaper than finding it in an exam.","family_question":"Can you teach me the thinking test, and why hints and answers gave different exam results?","listen_for":"You ask what a task is teaching you before using AI, and you know the feeling of understanding cannot be trusted.","then_ask":"What is one job at home where the tool should do it, and one where it should not?","no_login_required":true}'::jsonb, 'explorer', 31, 0),
  ('ks3-27-when-it-turns-on-you', 'What would you actually do first if it happened to a friend? Then: who at school would you tell?', 'builder', '{"headline":"What we taught today, and one thing to try at home","taught":"Today your child learned why conflict online grows faster than the same thing said out loud: three brakes are missing, the face that would stop you, the privacy that would keep it small, and the forgetting that would let it end. They learned four behaviours by name, bullying, harassment, stalking and coercive control, including that three of those are criminal offences. And they learned three moves that end it: name it, save it, say it.","try_this":"Do not ask whether anything is going on. Ask a lighter question instead: what is the fastest a group chat has ever gone wrong that you have seen? It is a story rather than a confession, and it usually tells you more.","family_question":"What is the fastest a group chat has ever gone wrong that you have seen?","listen_for":"You know why things escalate online, and you name it, save it before you reply, and say it to one person who can act.","then_ask":"Why does saving it before replying matter?","say_this":"If anything online ever turns on you, or on a friend, bring it to me straight away. Save it before you reply, and you will not be in trouble for showing me.","passport":"This lesson has a place on your child''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your child does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday. The skill this lesson builds is being able to name a harm and knowing the route to help.","no_login_required":true}'::jsonb, 'explorer', 31, 0),
  ('ks3-34-who-owns-what-you-make', 'If you made a picture with an AI tool and then changed half of it by hand, whose would it be?', 'shaper', '{"taught":"Today we looked at who owns what your child makes. In the UK copyright is automatic, so their drawings, photos and writing are theirs from the moment they make them, and posting gives the app a licence rather than ownership. We also taught fair dealing, the UK''s narrow rule for using other people''s work, why crediting someone is not the same as permission, what happens to a song under a video, and the classroom rule for anything made with AI: credit the tool and say what you did.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your teenager''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your teenager does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday. The skill this lesson builds is saying who owns a piece of work and using other people''s work fairly.","try_this":"Next time a video or post comes up at home, ask together: whose is it? Whose song, whose photo, whose words. It takes ten seconds, and there is often more than one owner in a single post.","family_question":"Explain to me why posting a photo gives an app a licence, not ownership.","listen_for":"You know copyright is automatic, credit is not permission, and work made with AI gets the tool credited.","then_ask":"Whose song, photo and words are in the last video you watched?","no_login_required":true}'::jsonb, 'explorer', 30, 0),
  ('ks4-15-manipulation-persuasion', 'What was the last thing online that made you feel a sudden urge to buy it, share it or argue with it, and who made money from that feeling?', 'independent', '{"taught":"Today your teenager learned to name the persuasion techniques aimed at them online: fake urgency, rage bait, flattery from influencers and FOMO, plus the dark patterns shops and apps use at checkout. The skill is simple and powerful: naming the technique out loud takes away most of its power.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your teenager''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your teenager does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday. Ask them to name the technique the next advert in the room is using.","try_this":"Next time you shop online together and a countdown or an only 2 left banner appears, ask them to name the technique. Then let them catch one being used on you. They will enjoy that part.","family_question":"Can you teach me to name the technique? Catch one being used on me.","listen_for":"You notice the pull, name it as urgency, outrage, flattery or FOMO, and follow the money.","then_ask":"Which technique did the last advert in this room use on me?","no_login_required":true}'::jsonb, 'shaper', 30, 0),
  ('ks4-16-consent-images-law', 'If a friend of yours was being pressured to share a photo, what would you want them to know?', 'independent', '{"taught":"Today we covered consent, images and UK law in a calm, factual way: real consent is freely given and can always be taken back, and the law makes any sexual image of an under 18 illegal to make, hold or share, even of yourself, and agreeing is no defence. We also made sure every pupil knows about Report Remove, the confidential Childline and Internet Watch Foundation tool that works to get images of under 18s taken down, and that asking for help never gets them in trouble.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your teenager''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your teenager does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday. Ask them what the three questions are, and let the conversation be short if they want it short: they know the answers now.","try_this":"Look up Report Remove together at childline.org.uk, just so it is a known name in your house before anyone ever needs it. Knowing the route in advance is what makes a young person use it.","family_question":"If a friend of yours was being pressured to share a photo, what would you want them to know?","listen_for":"You know real consent is free and can be taken back, what the law says about images of under 18s, and that Report Remove exists.","then_ask":"Can you show me where Report Remove is, so we both know?","say_this":"If a photo ever gets out, or someone pushes you for one, come to me. There is a free way to get it taken down, and you will not be in trouble.","no_login_required":true}'::jsonb, 'shaper', 32, 0),
  ('ks4-17-sextortion', 'If something went wrong online, who would you tell first, and what would make telling easier?', 'independent', '{"taught":"Today we taught your child about sextortion, the blackmail scam the National Crime Agency warned every UK school about in 2024, which most often targets teenage boys. They learned how it starts, why paying is not the way out, and the three lifelines: do not pay, do not keep it secret, report it to CEOP and Report Remove.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your teenager''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your teenager does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday. You do not need to quiz them on this one. One sentence from you does more.","try_this":"Tell your child directly, in your own words: if anything like this ever happens, you can come to me, you will not be in trouble, and you will not lose your phone. Fear of blame and fear of losing the phone can both keep young people silent, and one calm sentence from you answers both.","family_question":"If something went wrong online, who would you tell first, and what would make telling easier?","listen_for":"You know the three lifelines, do not pay, do not keep it secret, report it, and that the crime belongs to the blackmailer.","then_ask":"Why does paying make it worse rather than ending it?","say_this":"If anything like this ever happens, you can come to me. You will not be in trouble, and you will not lose your phone.","no_login_required":true}'::jsonb, 'shaper', 30, 0),
  ('ks4-18-radicalisation-misogyny', 'Who makes money when a video makes you angry?', 'independent', '{"taught":"Today we looked at how online pipelines work: content that starts as gym, money or confidence advice and is escalated by recommendations towards us versus them thinking, with misogyny a common version aimed at teenage boys. We taught the pipeline check, three calm questions: who wants me angry, what happens if I keep watching, who am I being turned against?","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on your teenager''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your teenager does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday. Ask them who profits when content makes people angry, and listen to how precisely they can answer.","try_this":"Ask your teenager to teach you the three questions, then run them together on one video from your own feed, not theirs. Doing it on your feed first keeps it a skill you share rather than an inspection.","family_question":"Who do you think makes money when a video makes you angry?","listen_for":"You know a pipeline starts with reasonable content and escalates, and you ask who wants you angry and who you are being turned against.","then_ask":"Why does the movement happen gradually rather than all at once?","say_this":"Angry videos pay somebody. If one ever seems to be turning you against people, I would rather hear about it than have you watch it alone.","no_login_required":true}'::jsonb, 'shaper', 30, 0),
  ('ks4-19-readiness-at-16', 'If every app arrived on your phone tomorrow, what is the first setting you would change before you posted anything?', 'independent', '{"taught":"Today was the module the whole scheme builds towards: what happens on the day your teen turns 16 and full social media access arrives all at once. They wrote a personal arrival plan with three parts: defaults decided in advance, a first week audit of what the feed serves them, and an exit rule written before it is needed.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place on one of the last pages of the passport, and it is the page the whole journey pointed at: the arrival plan for full access. The class met it today. It goes on the page when your teenager does its own short check at home, in their app. The passport is proof of readiness, never a licence, and the plan they wrote today is theirs. Ask to see it, and tell them which default you would set first.","try_this":"Ask your teen to talk you through their arrival plan, then write your own exit rule for your own phone alongside them. It lands ten times harder when they see you hold yourself to one too.","family_question":"Can you teach me your arrival plan? Explain why the first week decides the feed.","listen_for":"You know access at sixteen is a cliff edge, a fresh account learns fastest, and an exit rule is written before you need it.","then_ask":"What should my exit rule be for my own phone?","no_login_required":true}'::jsonb, 'shaper', 34, 0),
  ('ks4-28-the-money-and-the-odds', 'What is the most anyone you know has spent on a game without meaning to? Then: how would you even tell?', 'independent', '{"headline":"What we taught today, and one thing to try at home","taught":"Today your child learned how games and betting apps price a chance rather than a thing: pounds become a game currency, the pack never divides evenly into the item, and the leftover that buys nothing is deliberate. They learned what a house edge is and why one go is luck while ten thousand goes is arithmetic. And they learned the question that does the most work, which is how fast is the loop between putting money on and finding out, because speed is what decides how much harm a product does.","try_this":"Do not ask whether they spend money on games. Ask them to price one instead: how much is one crate in real pennies? It is a maths question rather than a confession, and the answer usually opens the conversation on its own.","family_question":"Can you teach me the price, the odds, the loop? Price one crate in real pennies.","listen_for":"You know a chance is a different purchase from an item, odds are not a promise, and the speed of the loop decides the harm.","then_ask":"Why is a weekly draw treated differently from a slot machine?","passport":"This lesson has a place on your child''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your child does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday. The skill this lesson builds is working out what something really costs and saying when it has stopped being a game.","no_login_required":true}'::jsonb, 'shaper', 32, 0),
  ('ks4-29-did-not-go-looking', 'What is the strangest thing an app has ever shown you that you never asked for? Then, lighter: how do you think it decided?', 'independent', '{"headline":"What we taught today, and one thing to try at home","taught":"Today your child learned why the hardest things to see online usually arrive rather than get searched for: a feed is a guess about what holds attention, and distress holds attention. They learned an accurate version of what that content does, which is not that it makes anybody do anything, but that repetition makes a serious thing look ordinary. They learned that an offer of easy money from somebody who half knows them is how recruitment into drug supply actually begins. And they learned three moves that work on all of it: stop it, report it, say it.","try_this":"The line worth saying out loud at some point this week, in your own words, is this one: if you ever see something you wish you had not, you are not in trouble, and there is no time limit on telling me. It costs nothing to say and it is the sentence that gets used months later.","family_question":"What is the strangest thing an app has ever shown you that you never asked for?","listen_for":"You know distressing content arrives rather than gets searched for, and you stop it, report it and say it to one person.","then_ask":"Why is stopping it the only move that is on a clock?","say_this":"If you ever see something you wish you had not, you are not in trouble, and there is no time limit on telling me.","passport":"This lesson has a place on your child''s passport page, the readiness record home and school build on the road to sixteen. The class met it today; it goes on the page when your child does its own short check at home, in their app. Each stage is stamped when it is ready, not at a birthday. The skill this lesson builds is knowing what to do with something you never asked to see, and knowing you are not in trouble for it.","no_login_required":true}'::jsonb, 'shaper', 32, 0),
  ('ks5-20-ai-mastery-data-rights', 'What do you think our family has traded, without noticing, for the free apps on our phones?', 'after', '{"taught":"Today your young adult learned to move from using AI to mastering it: prompting well, verifying outputs because confident errors are built into how these tools work, supervising AI that can act on their behalf, and understanding what free tools take in data plus the legal rights they hold over their own. The standard we gave them: use it, check it, own it, never submit what you cannot defend.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place in the passport''s final chapter, the Ready at sixteen page, which ends not with permission granted but with judgement owned. The class met it today; it goes on the page when they do its own short check at home, in their app. Ask them how they check an AI''s work before their name goes on it, and try their method on something of yours.","try_this":"Ask them to show you one AI tool they actually use, then ask them to show you how they would check something it produced. Watching them verify is the whole lesson in thirty seconds, and they will enjoy being the expert.","family_question":"Can you teach me how you check an AI''s work before your name goes on it?","listen_for":"You know confident errors are built in, so you use it, check it and own it, and never submit what you cannot defend.","then_ask":"What has our family traded for the free apps on our phones?","no_login_required":true}'::jsonb, 'independent', 30, 0),
  ('ks5-21-digital-identity-future-work', 'Which skill in our family gets MORE valuable now that everyone has AI?', 'after', '{"taught":"Today your young adult learned to treat their online record as a portfolio an admissions tutor or employer will actually read, and to test any skill with one question: does it get more valuable or less valuable when everyone has AI? The honest answer from the evidence is churn, not collapse, and the skills that climb are human ones: judgement, taste, trust and accountability.","headline":"What we taught today, and one thing to try at home","passport":"This lesson has a place in the passport''s final chapter, the Ready at sixteen page, which ends not with permission granted but with judgement owned. The class met it today; it goes on the page when they do its own short check at home, in their app. Ask them which human skill they are betting on, and tell them the one that has carried you.","try_this":"Sit together and search each of your names in a private browsing window, then compare notes: what story does page one tell about each of you, and who wrote it?","family_question":"Explain to me the endurance test. Which skill gets more valuable when everyone has AI?","listen_for":"You treat your online record as a portfolio, and you know judgement, taste and trust climb while routine work compresses.","then_ask":"Which of my skills would pass the endurance test?","no_login_required":true}'::jsonb, 'independent', 29, 0);

create temp table lines_373 (module_id text not null, idx int not null, slide_type text not null, line text not null, primary key (module_id, idx)) on commit drop;
insert into lines_373 (module_id, idx, slide_type, line) values
  ('eyfs-01-screens-kindness', 0, 'interactive', 'Do the star breath with them: arms out wide as the star grows, breathe in, and out as it shrinks.'),
  ('eyfs-01-screens-kindness', 1, 'title', 'Read the title out. Say: Pebble has a question for us today. Are things on a screen real, or made up?'),
  ('eyfs-01-screens-kindness', 2, 'digi', 'Read Pebble''s lines in a bouncy voice. Let them answer Pebble''s question before you move on.'),
  ('eyfs-01-screens-kindness', 3, 'objective', 'Read the big line: I can ask a grown up if something on a screen is real. Say: that is you and me today.'),
  ('eyfs-01-screens-kindness', 4, 'discussion', 'Let them tell you one thing. Then tell them one thing you saw on a screen today, so it goes both ways.'),
  ('eyfs-01-screens-kindness', 5, 'keywords', 'Say each word, then its meaning. Ask them to say the word back to you. Three words is plenty.'),
  ('eyfs-01-screens-kindness', 6, 'choice', 'Read the question and both answers. Let them tap. Whatever they pick, read the feedback out, it is kind either way.'),
  ('eyfs-01-screens-kindness', 7, 'concept', 'Point at the two halves. Say: a photo is real. A dragon is made up. Ask: can you think of a made up thing you love?'),
  ('eyfs-01-screens-kindness', 8, 'diagram', 'Do the three steps together with actions: hand up for stop, hand over eyes for look, hand in the air for ask. Then say all three in a row.'),
